// Helper function to check if two tiles have compatible edges
// Returns 1 if they form an edge, 0 otherwise
int check_edge_compatibility(const vector<string>& grid, int r1, int c1, int r2, int c2) {
    int m1 = parse_mask(grid[r1][c1]);
    int m2 = parse_mask(grid[r2][c2]);

    // Directions: 1:Left, 2:Up, 4:Right, 8:Down

    // Horizontal adjacency: (r1,c1)-(r1,c2)
    if (r1 == r2 && c1 < c2) {
        if ((m1 & 4) && (m2 & 1)) return 1; // (r1,c1)->Right, (r1,c2)->Left
        return 0;
    }

    // Vertical adjacency: (r1,c1)-(r2,c1)
    if (c1 == c2 && r1 < r2) {
        if ((m1 & 8) && (m2 & 2)) return 1; // (r1,c1)->Down, (r2,c1)->Up
        return 0;
    }

    return 0;
}

