    // However, grid indices in loop are checked against non-empty tiles.

    // Wait, parsing logic inside score function is slow if O(N^3) inside A*.
    // Precompute compatible pairs? No, grid changes.
    // N <= 10. Loop is 100 pairs. Fast enough.

    for (int i = 0; i < N; ++i) {
        for (int j = 0; j < N; ++j) {
            if (grid[i][j] == '0') continue; // Empty

            // Check Down
