#include <iostream>
#include <vector>

using namespace std;

int main() {
    // Optimize I/O operations
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int N, M;
    if (!(cin >> N >> M)) return 0;

    // Structure to hold coordinates (row, col)
    // 0-indexed, top-left is (0,0)
    struct Point {
        int r, c;
    };

    // Store the coordinates. Input provides M coordinates.
    // i_0, j_0 is start. Others are targets.
    vector<Point> points(M);
    for (int i = 0; i < M; ++i) {
        cin >> points[i].r >> points[i].c;
    }

    // We start at points[0] and must visit points[1]...points[M-1] in order.
    // Strategy: Move directly towards the next target.
    // Maximum Manhattan distance in a 20x20 grid is 38.
    // With M=40, there are M-1 = 39 segments.
    // Total maximum steps = 39 * 38 = 1482.
    // The allowed budget is 2 * N * M = 1600.
    // Thus, simple walking (using 'M' for Move) is always within the limit
    // and satisfies the condition of visiting all targets.
    // No need for 'S' (Slide) or 'A' (Alter) actions.

    for (int i = 0; i < M - 1; ++i) {
        Point current = points[i];
        Point target = points[i+1];

        // Adjust row
        if (target.r > current.r) {
            for (int k = 0; k < target.r - current.r; ++k) {
                cout << "M D\n";
            }
        } else if (target.r < current.r) {
            for (int k = 0; k < current.r - target.r; ++k) {
                cout << "M U\n";
            }
        }

        // Adjust column
        if (target.c > current.c) {
            for (int k = 0; k < target.c - current.c; ++k) {
                cout << "M R\n";
            }
        } else if (target.c < current.c) {
            for (int k = 0; k < current.c - target.c; ++k) {
                cout << "M L\n";
            }
        }
    }

    return 0;
}
