vector<Point> sardines;
vector<int> xs, ys;
// Precompute unique sorted coordinates
map<int, int> x_map, y_map;

// Prefix sum grids. 
// pm[i][j] stores sum of mackerels in range rows [0..i] cols [0..j] (compressed)
// Dimensions: (U+1) x (V+1)
int** pm, **ps;
int U, V;

// Helper to query range sum [x1, x2] x [y1, y2] (inclusive in compressed coords)
// Corresponds to compressed indices x1..x2 and y1..y2
inline int query_m(int cx1, int cx2, int cy1, int cy2) {
    if (cx1 > cx2 || cy1 > cy2) return 0;
    int res = pm[cx2 + 1][cy2 + 1];
    res -= pm[cx1][cy2 + 1];
    res -= pm[cx2 + 1][cy1];
    res += pm[cx1][cy1];
    return res;
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

