    mackerels.resize(n);
    for (int i = 0; i < n; ++i) {
        cin >> mackerels[i].x >> mackerels[i].y;
        mackerels[i].id = i;
    }

    sardines.resize(n);
    for (int i = 0; i < n; ++i) {
        cin >> sardines[i].x >> sardines[i].y;
        sardines[i].id = i + n;
    }

