    vector<int> temp_xs, temp_ys;
    for (auto &p : mackerels) temp_xs.push_back(p.x);
    for (auto &p : sardines) temp_xs.push_back(p.x);
    for (auto &p : mackerels) temp_ys.push_back(p.y);
    for (auto &p : sardines) temp_ys.push_back(p.y);

